def evolve(task, model, store, rounds):
    population = [model.propose(task, docs=[])]
    for _ in range(rounds):
        choice = model.assess_gap(task, population)   # retrieval gate
        if choice == "retrieve":
            queries = model.refine_queries(task, population)   # inner loop
            docs = rank_by_predicted_score(search(queries), task)
            store.add(docs)
        elif choice == "reuse":
            docs = store.best_for(task)
        else:
            docs = []
        children = parallel_map(lambda d: model.propose(task, docs=d), docs)  # outer loop
        scored = [(c, task.score(c)) for c in children]
        store.record(docs, scored)   # later searches learn from outcomes
        population = keep_best(population, scored)
    return best(population)
